        check('[73-5] เปิดแผนได้', (await bp.openBranchPlan(p1)) === true &&
              bp.currentBranchPlan().path === p1);
        check('[73-5] เปิดแล้วยังไม่มีงานค้าง', bp.isBranchPlanDirty() === false);
