    // ---- mention → Wiki: ชื่อถูกไฮไลต์ + มี map ไปไฟล์ ----
    activate(t.file);
    t.editor.setMarkdown(orig + '\n\nคืนนั้นเขาไปหา ยัยแมวเก้าชีวิต ที่ ตลาดน้ำโบราณ');
    refreshMentions(t.editor.view);
    await new Promise((r) => setTimeout(r, 150));
