      const p2 = after.findIndex((nd) => nd.textContent === 'หน้า');
      let off2 = 0; vsp.state.doc.forEach((nd, o) => { if (nd.textContent === 'หน้า') off2 = o; });
      vsp.dispatch(vsp.state.tr.setSelection(TS2.create(vsp.state.doc, off2 + 1, off2 + 1 + 4)));
