    const effBold = effectiveShortcuts().find((x) => x[3] === 'fmt' && x[4] === 'bold');
    check('คำสั่งที่ไม่ override ยังใช้ค่าเริ่มต้น', effBold[0] === 'KeyB', JSON.stringify(effBold));
    state.settings.shortcuts = {};
