          check('[r3-9] commonPrefix ปอกโฟลเดอร์ชั้นนอกที่ทุกไฟล์ใช้ร่วมกัน',
                commonPrefix(['proj/a.md', 'proj/b/c.md']) === 'proj/' &&
                commonPrefix(['a.md', 'b.md']) === '');
          const ov9 = await showHomeDialog();
          await new Promise((r) => setTimeout(r, 350));
