          acts.querySelector('.home-btn-close').click();
          await new Promise((r) => setTimeout(r, 120));
          check('[r3-9] กดปุ่มปิดแล้วกล่องหายจริง', !document.body.contains(ov9));
          [...document.querySelectorAll('.k-overlay')].forEach((o) => o.remove());
