                + ' · trace ' + trace66.join(',') + ' · focus ' + ae66 + ' · sh/ch ' + geo0.join('/') + '→' + [bodyOf().scrollHeight, bodyOf().clientHeight].join('/') + ' same=' + (bodyOf() === b2)
