        let tdoc63 = await AC63.readAlbumDoc(kapi, state.root, 'ทดสอบ');
        tdoc63 = TG63.addTag(tdoc63, 'sunset.png', 'ฉากกลางคืน');
        tdoc63 = TG63.addTag(tdoc63, 'sunset.png', '@ยัยแมวเก้าชีวิต');
