          check('[156-10] ฉากที่ล็อกไม่ถูกแทนที่', r3.count === 0 && parseMdFile(await kapi.readFile(fr)).body === 'แทนที่แล้ว156');
          const ui = await R.openProjectReplace('');
          check('[156-10] กล่องแทนที่เปิดได้', !!document.querySelector('.k-replace'));
          ui.close();
          const host = el('div');
