          check('[161-S4] ★ ค้นสดหลังหยุดพิมพ์ ~250ms', ui.hits().length === 2);
          const pOld = ui.doSearch('qqkey161'), pNew = ui.doSearch('qqmid161');
          await Promise.all([pOld, pNew]);
