          hidePanel('search');
          for (const r of [s1, kA, kB]) await kapi.remove(await kapi.join(dir, r.fileName)).catch(() => {});
          await JS.mutateJson(kapi, sf, (d) => { d.chapters[ch.guid] = (d.chapters[ch.guid] || []).filter((r) => ![s1.id, kA.id, kB.id].includes(r.id)); });
