          const nameNow = () => (document.querySelector('#props-body .props-name-input') || {}).value;
          showPanel('props-panel');
          await openScene(fA, null);
          check('[161-P1] ★ เปิดฉาก ก → แผงคุณสมบัติเป็นของฉาก ก', await until159(() => nameNow() === 'แผงตามก161', 5000), nameNow());
          await openScene(fB, null);
          check('[161-P1] ★★ สลับไปแท็บ ข → แผงเปลี่ยนตาม (ไม่ค้างฉากเก่า)', await until159(() => nameNow() === 'แผงตามข161', 5000), nameNow());
          activate(fA);
          check('[161-P1] สลับกลับแท็บ ก → แผงกลับเป็น ก', await until159(() => nameNow() === 'แผงตามก161', 5000), nameNow());
          // แท็บชนิดอื่น (ไฟล์ข้อความล้วน) → แผงว่าง ไม่ค้างฉากเดิม
