          resetPanels(); await wU(250);
          showPanel('props', { targetId: 'docs', side: 'right', forceMove: true });
          await wU(300);
          const panelEl = () => document.querySelector('#app-root .k-panel[data-panel-id="props"], .k-float-panel[data-panel-id="props"]');
          const headBtn = (act) => { const p = panelEl(); return p && p.querySelector(':scope > .k-panel-head .k-panel-btn-' + act); };
          check('[161-U] เงื่อนไข: แผงคุณสมบัติเปิดอยู่เป็นแผงเดี่ยว (มีปุ่มครบบนหัว)',
                !!headBtn('menu') && !!headBtn('collapse') && !!headBtn('float') && !!headBtn('close'));
          // ── U2: ปุ่มเป็นคอมโพเนนต์เดียว — กดด้วยคีย์บอร์ดได้ · มีคำอธิบายบรรทัดสอง · ชื่อมีคีย์ลัดจริง ──
          const allBtns = [...document.querySelectorAll('#app-root .k-panel-head .k-panel-btn')];
